content = r['content']
# Remove line number prefixes - they look like " 1\ttext" or " 100\ttext"
import re
actual_lines = []
for line in content.split('\n'):
    # Match pattern: optional spaces, number, tab, then text
    m = re.match(r'^\s*(\d+)\t(.*)$', line)
    if m:
        actual_lines.append(m.group(2))
    else:
        actual_lines.append(line)

print(f"Actual lines: {len(actual_lines)}")
# Print around key areas
for i, line in enumerate(actual_lines):
    if 'class Result' in line or 'class Match' in line or 'class Parser' in line:
        print(f"\n=== Line {i+1}: {line}")
        for j in range(max(0,i-1), min(len(actual_lines), i+5)):
            print(f"  {j+1}: {actual_lines[j]}")
